import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 2

def design(feats):
    # Filter out derived features for driver selection
    non_derived_ids = [fid for fid, t in zip(feats.ids, feats.types) if t != 'derived']

    # Calculate effect sizes using mean difference
    effect_sizes = []
    for fid in non_derived_ids:
        idx = feats.column(fid)
        y1_mean = np.mean(feats.x[feats.y == 1, idx])
        y0_mean = np.mean(feats.x[feats.y == 0, idx])
        effect_sizes.append(abs(y1_mean - y0_mean))

    # Select top features by effect size
    top_indices = np.argsort(effect_sizes)[::-1][:MAX_DRIVERS]
    drivers = tuple(non_derived_ids[i] for i in top_indices if effect_sizes[i] > 0)

    # If no strong drivers, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build regression features including interactions
    columns = list(drivers)
    products = []

    # Add pairwise products between drivers
    for i in range(len(drivers)):
        for j in range(i+1, len(drivers)):
            # Only include products if both features are in feats.ids
            if drivers[i] in feats.ids and drivers[j] in feats.ids:
                products.append((drivers[i], drivers[j]))

    # Add interaction terms to columns (only valid feature ids)
    valid_products = []
    for a, b in products:
        if a in feats.ids and b in feats.ids:
            columns.append(f"{a}x{b}")
            valid_products.append((a, b))

    # Create weighted score using effect sizes
    loadings = {}
    for fid, effect_size in zip(non_derived_ids, effect_sizes):
        if effect_size > 0 and fid in feats.ids:
            loadings[fid] = effect_size

    return Design(drivers=drivers, columns=tuple(columns), products=tuple(valid_products), loadings=loadings)
